const contacts=[['Carlos Lima','Montagem de móveis'],['Beatriz Santos','Jardinagem'],['Marcos Oliveira','Hidráulica']];document.querySelectorAll('.contact').forEach((b,i)=>b.onclick=()=>{document.querySelectorAll('.contact').forEach(x=>x.setAttribute('aria-pressed','false'));b.setAttribute('aria-pressed','true');document.querySelectorAll('[data-name]').forEach(x=>x.textContent=contacts[i][0]);document.querySelectorAll('[data-initial]').forEach(x=>x.textContent=contacts[i][0][0]);document.querySelector('[data-area]').textContent=contacts[i][1];});document.querySelector('.list input').oninput=e=>document.querySelectorAll('.contact').forEach(b=>b.hidden=!b.textContent.toLowerCase().includes(e.target.value.toLowerCase()));document.querySelector('form').onsubmit=e=>{e.preventDefault();let field=document.querySelector('textarea');if(!field.value.trim())return;let bubble=document.createElement('div');bubble.className='bubble mine';bubble.textContent=field.value;document.querySelector('.history').append(bubble);field.value='';bubble.scrollIntoView({block:'nearest'});};